"""R1: docs/I18N-SHEET.csv (the owner's vocabulary review sheet) is generated by i18n/review_sheet.py; it must not drift."""
from __future__ import annotations

import csv
import pathlib
import shutil

import pytest

from i18n import review_sheet as rs

needs_node = pytest.mark.skipif(shutil.which("node") is None, reason="node renders the TypeScript UI templates")


@needs_node
def test_the_sheet_csv_is_up_to_date():
    assert rs.main(["--check"]) == 0, "run: cd server && ../.venv/bin/python -m i18n.review_sheet --csv-only"


@needs_node
def test_check_detects_drift_and_a_missing_file(tmp_path: pathlib.Path):
    out = tmp_path / "SHEET.csv"
    assert rs.main(["--check"], out) == 1
    assert rs.main(["--csv-only"], out) == 0 and rs.main(["--check"], out) == 0
    out.write_bytes(out.read_bytes().replace("Слой".encode(), "Слой2".encode()))
    assert rs.main(["--check"], out) == 1


@needs_node
def test_the_sheet_is_complete_and_deterministic():
    rows = rs.build_rows()
    assert rows == rs.build_rows()
    assert [r["n"] for r in rows] == list(range(1, len(rows) + 1))
    assert {r["layer"] for r in rows} == set(rs.LAYERS)
    assert all(r["example"].strip() and r["bg"].strip() and r["en"].strip() and r["key"] for r in rows)
    assert {r["state"] for r in rows} <= set(rs.STATES)
    from i18n.catalog import MESSAGES
    assert sum(r["layer"] == "Съобщение" for r in rows) == len(MESSAGES)
    assert 800 <= len(rows) <= 1600


def test_the_csv_file_has_a_bom_and_the_columns():
    raw = rs.OUT_CSV.read_bytes()
    assert raw.startswith("﻿".encode())
    header = next(csv.reader(raw.decode("utf-8-sig").splitlines()))
    assert header == rs.HEADERS
